// ─── Shared specimen helpers ────────────────────────────────────────────────
type RowData = { label: string; className: string; sample: string; nowrap?: boolean };
type RowAlign = "center" | "flex-start";

function BreakpointHeading({ children }: { children: string }) {
  return (
    <h3
      style={{
        fontFamily: "var(--font-body)",
        fontSize: 11,
        fontWeight: 600,
        textTransform: "uppercase",
        letterSpacing: "0.08em",
        color: "var(--text-faint)",
        margin: "0 0 16px",
      }}
    >
      {children}
    </h3>
  );
}

function SpecimenRow({
  label,
  className,
  sample,
  nowrap,
  sampleMaxWidth,
  align,
  isFirst,
}: RowData & { sampleMaxWidth?: number; align: RowAlign; isFirst: boolean }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: align,
        gap: 24,
        padding: "40px 0",
        borderTop: isFirst ? "none" : "1px solid var(--border-soft)",
      }}
    >
      <div style={{ width: 220, flexShrink: 0, display: "flex", flexDirection: "column", gap: 6 }}>
        <span style={{ fontFamily: "var(--font-body)", fontSize: 12, fontWeight: 500, color: "var(--text-muted)" }}>
          {label}
        </span>
        <code
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: 11,
            color: "var(--text-strong)",
            background: "var(--surface-sunken)",
            padding: "2px 6px",
            borderRadius: 4,
            alignSelf: "flex-start",
            lineHeight: 1.4,
          }}
        >
          .{className}
        </code>
      </div>
      <div
        className={className}
        style={{
          color: "var(--text-strong)",
          whiteSpace: nowrap ? "nowrap" : "normal",
          maxWidth: sampleMaxWidth,
        }}
      >
        {sample}
      </div>
    </div>
  );
}

function ScaleSection({
  breakpoint,
  rows,
  align,
  sampleMaxWidth,
}: {
  breakpoint: string;
  rows: RowData[];
  align: RowAlign;
  sampleMaxWidth?: number;
}) {
  return (
    <section style={{ marginBottom: 48 }}>
      <BreakpointHeading>{breakpoint}</BreakpointHeading>
      <div style={{ display: "flex", flexDirection: "column" }}>
        {rows.map((r, i) => (
          <SpecimenRow
            key={r.label}
            label={r.label}
            className={r.className}
            sample={r.sample}
            nowrap={r.nowrap}
            sampleMaxWidth={sampleMaxWidth}
            align={align}
            isFirst={i === 0}
          />
        ))}
      </div>
    </section>
  );
}

