const GROUPS: FilterGroup[] = [
  {
    id: "creator",
    label: "Creator",
    options: [
      { value: "all", label: "Base 44 + Community" },
      { value: "base44", label: "Base44" },
      { value: "community", label: "Community" },
    ],
  },
  {
    id: "price",
    label: "Price",
    options: [
      { value: "all", label: "Free + Paid" },
      { value: "free", label: "Free" },
      { value: "paid", label: "Paid" },
    ],
  },
];

