export const Sizes: Story = {
  render: () => (
    <div style={SECTION}>
      <div style={ROW}>
        <span style={H}>D/T</span>
        <PlayPauseButton size="dt" />
        <PlayPauseButton size="dt" playing />
      </div>
      <div style={ROW}>
        <span style={H}>M</span>
        <PlayPauseButton size="m" />
        <PlayPauseButton size="m" playing />
      </div>
    </div>
  ),
};

